    start = omp_get_wtime();
    mandelbrot_block_k << < grid, blocks >> > (dwellsD, w, h, cmin, cmax, 0, 0, W / INIT_SUBDIV, 1);
    cudaThreadSynchronize();
    end = omp_get_wtime();
    printf("Work took %f seconds\n", end - start);
